create table public.relationship_clearances(id uuid primary key default gen_random_uuid(),administration_id uuid not null references public.administrations(id) on delete cascade,rental_relationship_id uuid not null references public.rental_relationships(id) on delete cascade,scope text not null default 'HABITEX_RECORDS',status text not null check(status in('ELIGIBLE','ISSUED','VOIDED')),issued_at timestamptz,issued_by_person_id uuid references public.people(id) on delete set null,statement text not null default 'Constancia basada exclusivamente en los registros de Habitex; no constituye declaración sobre obligaciones externas a la plataforma.',created_at timestamptz not null default now()); create unique index relationship_clearance_issued_uq on public.relationship_clearances(rental_relationship_id) where status='ISSUED'; create index relationship_clearances_admin_idx on public.relationship_clearances(administration_id); alter table public.relationship_clearances enable row level security; grant select on public.relationship_clearances to authenticated; revoke insert,update,delete on public.relationship_clearances from anon,authenticated; create policy clearance_select on public.relationship_clearances for select to authenticated using(public.is_administration_member(administration_id) or public.can_view_relationship(rental_relationship_id));
create or replace function public.create_act(p_relationship_id uuid,p_act_type public.act_type,p_general_observations text default null) returns public.acts language plpgsql security definer set search_path='' as $$ declare r public.rental_relationships; a public.acts; actor uuid; n int; begin select * into r from public.rental_relationships where id=p_relationship_id; if not found then raise exception 'RENTAL_RELATIONSHIP_NOT_FOUND'; end if; if public.can_manage_administration(r.administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; select person_id into actor from public.accounts where auth_user_id=auth.uid(); select coalesce(max(version_number),0)+1 into n from public.acts where rental_relationship_id=r.id and act_type=p_act_type; insert into public.acts(administration_id,rental_relationship_id,act_type,status,version_number,general_observations,created_by_person_id) values(r.administration_id,r.id,p_act_type,'DRAFT',n,nullif(btrim(p_general_observations),''),actor) returning * into a; return a; end $$;
create or replace function public.add_act_item(p_act_id uuid,p_category text,p_item_name text,p_condition_text text default null,p_observations text default null,p_sort_order int default 0) returns public.act_items language plpgsql security definer set search_path='' as $$ declare a public.acts; x public.act_items; begin select * into a from public.acts where id=p_act_id; if not found then raise exception 'ACT_NOT_FOUND'; end if; if public.can_manage_administration(a.administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; if a.status<>'DRAFT' then raise exception 'ACT_NOT_EDITABLE'; end if; insert into public.act_items(act_id,category,item_name,condition_text,observations,sort_order) values(a.id,btrim(p_category),btrim(p_item_name),nullif(btrim(p_condition_text),''),nullif(btrim(p_observations),''),p_sort_order) returning * into x; return x; end $$;
create or replace function public.mark_act_ready(p_act_id uuid) returns public.acts language plpgsql security definer set search_path='' as $$ declare a public.acts; begin select * into a from public.acts where id=p_act_id for update; if not found then raise exception 'ACT_NOT_FOUND'; end if; if public.can_manage_administration(a.administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; if a.status<>'DRAFT' then raise exception 'INVALID_ACT_STATUS'; end if; update public.acts set status='READY_FOR_REVIEW',updated_at=now() where id=a.id returning * into a; return a; end $$;
create or replace function public.confirm_act(p_act_id uuid) returns public.acts language plpgsql security definer set search_path='' as $$ declare a public.acts; person uuid; begin select * into a from public.acts where id=p_act_id for update; if not found then raise exception 'ACT_NOT_FOUND'; end if; if a.status<>'READY_FOR_REVIEW' then raise exception 'ACT_NOT_READY'; end if; select person_id into person from public.accounts where auth_user_id=auth.uid(); if person is null or not exists(select 1 from public.rental_participants rp where rp.rental_relationship_id=a.rental_relationship_id and rp.person_id=person and rp.status='ACTIVE' and rp.participation_type in('TENANT','LESSOR')) then raise exception 'ACT_CONFIRMATION_NOT_ALLOWED'; end if; if exists(select 1 from public.acceptances x where x.person_id=person and x.subject_type='ACT' and x.subject_id=a.id) then raise exception 'ACT_ALREADY_CONFIRMED_BY_PERSON'; end if; insert into public.acceptances(administration_id,person_id,rental_relationship_id,document_type,document_version,purpose,subject_type,subject_id,accepted_at,method,evidence) values(a.administration_id,person,a.rental_relationship_id,'ACT',a.version_number::text,'CONFIRM_ACT','ACT',a.id,now(),'AUTHENTICATED_ACTION',jsonb_build_object('act_type',a.act_type::text)); if (select count(distinct x.person_id) from public.acceptances x join public.rental_participants rp on rp.person_id=x.person_id and rp.rental_relationship_id=a.rental_relationship_id and rp.status='ACTIVE' and rp.participation_type in('TENANT','LESSOR') where x.subject_type='ACT' and x.subject_id=a.id)>=2 then update public.acts set status='CONFIRMED',confirmed_at=now(),updated_at=now() where id=a.id returning * into a; end if; return a; end $$;
create or replace function public.issue_relationship_clearance(p_relationship_id uuid) returns public.relationship_clearances language plpgsql security definer set search_path='' as $$ declare r public.rental_relationships; c public.relationship_clearances; actor uuid; begin select * into r from public.rental_relationships where id=p_relationship_id for update; if not found then raise exception 'RENTAL_RELATIONSHIP_NOT_FOUND'; end if; if public.can_manage_administration(r.administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; if r.status<>'ENDED' then raise exception 'RELATIONSHIP_MUST_BE_ENDED'; end if; if exists(select 1 from public.charge_balances b where b.rental_relationship_id=r.id and b.balance>0) then raise exception 'OUTSTANDING_HABITEX_BALANCE'; end if; select person_id into actor from public.accounts where auth_user_id=auth.uid(); insert into public.relationship_clearances(administration_id,rental_relationship_id,status,issued_at,issued_by_person_id) values(r.administration_id,r.id,'ISSUED',now(),actor) returning * into c; return c; end $$;
revoke all on function public.create_act(uuid,public.act_type,text),public.add_act_item(uuid,text,text,text,text,int),public.mark_act_ready(uuid),public.confirm_act(uuid),public.issue_relationship_clearance(uuid) from public,anon; grant execute on function public.create_act(uuid,public.act_type,text),public.add_act_item(uuid,text,text,text,text,int),public.mark_act_ready(uuid),public.confirm_act(uuid),public.issue_relationship_clearance(uuid) to authenticated,service_role;